using System.Linq;using NUnit.Framework;using UnityEditor.SceneManagement;using UnityEngine;using EternalSteam.OpenWorld;
namespace EternalSteam.Tests{
public sealed class RailwayServicePanelTests{
[TestCase("StartRegionSandbox")][TestCase("OpenWorldSandbox")]
public void ServiceInputsAndCommandsAreSaved(string name){var scene=EditorSceneManager.OpenPreviewScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");try{var h=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CanvasWorldHud>(true)).Single();var v=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>();var s=v.Services;Assert.That(s,Is.Not.Null);Assert.That(s.Overview,Is.SameAs(v));Assert.That(s.Root.IsChildOf(v.Root),Is.True);foreach(var input in new[]{v.Railway.Resource,v.Railway.Load,v.Railway.Unload}){Assert.That(input.transform.IsChildOf(s.Cargo),Is.True);Assert.That(input.textComponent,Is.Not.Null);Assert.That(input.textViewport,Is.Not.Null);}Assert.That(s.Scroll.GetComponent<UnityEngine.UI.ScrollRect>().viewport.GetComponent<UnityEngine.UI.Mask>(),Is.Not.Null);Assert.That(s.Actions.Select(a=>a.Command),Is.EquivalentTo(new[]{"next-stop","configure","weapon-shape","weapon-next","weapon-install","weapon-remove","weapon-upgrade","weapon-charge"}));foreach(var a in s.Actions){Assert.That(a.Button.onClick.GetPersistentTarget(0),Is.SameAs(s));Assert.That(a.Button.onClick.GetPersistentMethodName(0),Is.EqualTo("Execute"));}Assert.That(s.Return.onClick.GetPersistentTarget(0),Is.SameAs(s));Assert.That(s.Root.GetComponentsInChildren<TMPro.TMP_Text>(true).All(t=>t.fontSize==18&&!t.enableAutoSizing),Is.True);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
}}
